#include <math.h>
#include <sys/time.h>
#include <cassert>
#include <iostream>

#define N 100000

extern int ml[N];      // below main()
extern int CC[N][2];   // below main()
extern int mia[N][2];  // below main()
extern int scnt[N];    // below main()

inline int nint(double d) { return static_cast<int>(0.5 + d); }
// http://comopt.ifi.uni-heidelberg.de/software/TSPLIB95/tsp95.pdf#page=6
int dist(int from, int to) {         // euc_2d()
  double xd = CC[from][0] - CC[to][0];
  double yd = CC[from][1] - CC[to][1];
  int d = nint(sqrt(xd*xd + yd*yd));
  return d;
}

int pred[N], succ[N];

inline int delta(int s, int i) {
  int old = pred[i];
  return dist(old, s) + dist(s, i) - dist(old, i);
}

const int distmax = 30000;
inline int workaround(int i)  { return 3*distmax - i; }


int main() {
  for (int i=0; i < N; ++i)  ml[i]-=1;  // make mona-lisa100K.opt.tour 0-based

  for (int i=0; i < N; ++i) {           // doubly linked list
    pred[ml[i]] = ml[(i+N-1)%N];
    succ[ml[i]] = ml[(i+1)%N];
  }

  int s = 0;
  for (int i=0; i < N; ++i)  { s = succ[s]; assert(s != 0 || i == N-1); }
  assert(s == 0);
  for (int i=0; i < N; ++i)  { s = pred[s]; assert(s != 0 || i == N-1); }
  assert(s == 0);

  for (s=0; s < N; ++s) {
    succ[pred[s]] = succ[s]; pred[succ[s]] = pred[s];  // remove(s)

    int min = std::numeric_limits<int>::max();
    int pos = -1;
    int cnt = 0;

    int min_local, pos_local, cnt_local;

    #pragma omp parallel private(min_local, pos_local, cnt_local)
    {
      min_local = min;
      pos_local = pos;
      cnt_local = cnt;

      #pragma omp for
      for (int i=0; i < N; ++i) {
        if (i == s)  continue;

        int ncost = delta(s, i);
        if (ncost < min_local) {
            min_local = ncost;
            pos_local = i;
            cnt_local = 1;
        } else if (ncost == min_local) {
            pos_local = i;
            cnt_local += 1;
        }
      }
      #pragma omp critical
      {
        if (min_local < min) {
          min = min_local;
          pos = pos_local;
          cnt = cnt_local;
        } else if (min_local == min) {
          pos = pos_local;
          cnt += cnt_local;
        }
      }
    }

    assert(min == mia[s][0]);
    assert(min == delta(s, succ[s]));
    assert(min == delta(s, pos));

    assert(cnt == scnt[s]);

    succ[pred[s]] = s; pred[succ[s]] = s;              // reinsert(s)
  }
}


























